import{_ as i,l,o as e,c as n,v as r,p as s,x as t,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"顶点覆盖 2 近似","description":"","frontmatter":{"title":"顶点覆盖 2 近似","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vertex-cover-approx.md","filePath":"cs/vertex-cover-approx.md","lastUpdated":1789023840000}'),c={name:"cs/vertex-cover-approx.md"};function _(m,a,u,C,P,x){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="顶点覆盖-2-近似" tabindex="-1">顶点覆盖 2 近似 <a class="header-anchor" href="#顶点覆盖-2-近似" aria-label="Permalink to &quot;顶点覆盖 2 近似&quot;">​</a></h1><div class="epigraph"><p>极大匹配的两端点构成顶点覆盖，大小 $\\le 2\\,\\mathrm{OPT}$；贪心按度没有常数比。</p><footer>—— 据 CLRS 第 35.1 节；Garey and Johnson, 1979；[近似比](/cs/approximation-ratio) 整理</footer></div><p>上一课<a href="/cs/bandit-ucb">UCB</a>收束不确定输入。主干已定义 \\(\\rho\\)-近似。缺口是顶点覆盖的匹配 2-近似。不重写 \\(\\rho\\) 定义。后课集合覆盖 \\(\\ln n\\)。顶点覆盖 NPC，精确回分支定界。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最小顶点覆盖：每边至少一个端点在 \\(C\\)。极大匹配 \\(M\\)：每条匹配边两端都进 \\(C\\)。\\(C\\) 覆盖：未匹配边的端点必与 \\(M\\) 关联否则 \\(M\\) 可扩。\\(|C|=2|M|\\)，而 OPT \\(\\ge|M|\\)（每条匹配边至少一个点），故 \\(|C|\\le 2\\,\\mathrm{OPT}\\)。</p><p>按剩余度贪心：无常数比（可任意差）。不要用那条当 2-近似。</p><h3 id="不是独立集-2-近似" tabindex="-1">不是独立集 2-近似 <a class="header-anchor" href="#不是独立集-2-近似" aria-label="Permalink to &quot;不是独立集 2-近似&quot;">​</a></h3><p>独立集与覆盖互补，但近似比对最大化独立集不能这样翻（\\(n-|C|\\) 相对 OPT 独立集可很差）。</p><p><span class="marginnote">CLRS 35.1。U. Vazirani 教材。后课集合覆盖贪心 \\(H_n\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>求极大匹配（任意极大，不必最大）。两端进覆盖。可再删冗余点（可选，不改善最坏 2）。</p>',11)),(e(),s(h,null,{default:t(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%9E%81%E5%A4%A7%E5%8C%B9%E9%85%8D%22%5D%20--%3E%20C%5B%22%E4%B8%A4%E7%AB%AF%E7%82%B9%E8%BF%9B%20C%22%5D%0A%20%20C%20--%3E%20TWO%5B%22%7CC%7C%20%E2%89%A4%202%20OPT%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>二分图可精确（König），不必近似。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>匹配下界 OPT。两端点上界 2。与 LP：分数覆盖松弛 + 舍入也 2，后课 LP 舍入。与花匹配：最大匹配给出更好下界但不改善这个 2-算法的最坏。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Unique Games 下的 2-\\(\\varepsilon\\) 硬度。不写加权覆盖（可 LP）。后课默认：无向顶点覆盖有 2-近似。下一课集合覆盖贪心。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>极大匹配两端点：2-近似。</li><li>度贪心无常数比。</li><li>独立集不能同样翻。</li><li>出处：CLRS 第 35.1 节。</li></ul>',7))])}const b=i(c,[["render",_]]);export{f as __pageData,b as default};
